// Where each take sits in each frame, with no React: B (presenter) and C (multivideo) draw with this, and plan.ts
// exports the same math as JSON for the layered render. Sizes in output pixels; everything scales with the width
// (1080p and 4K look the same, only bigger).
import { interpolate, spring } from "remotion";
import { FPS } from "./common";

/** Length of each take on the timeline. */
export const TAKE_SECONDS = 9;
export const TAKE_FRAMES = TAKE_SECONDS * FPS;
/** Synthetic takes generated by the harness (bench/public/footage/take-N.mp4). */
export const N_TAKES = 4;
const SOURCE = { w: 1920, h: 1080 };
/** Point of interest in the 1920x1080 take (where the synthetic subject drifts). */
const FOCUS = { x: 1060, y: 560 };

export const take = (i: number) => `footage/take-${(i % N_TAKES) + 1}.mp4`;

export type Rect = { x: number; y: number; w: number; h: number };
export type Box = Rect & { radius: number };
export type Frame = { box: Box; e: number; video: Rect };

/** Take segments that fit in `total` frames. */
export const segments = (total: number) =>
  Array.from({ length: Math.ceil(total / TAKE_FRAMES) }, (_, i) => ({
    i,
    start: i * TAKE_FRAMES,
    frames: Math.min(TAKE_FRAMES, total - i * TAKE_FRAMES),
  }));

export const card = (W: number, H: number): Box => {
  const u = W / 1920;
  return { x: Math.round(0.52 * W), y: Math.round(0.1 * H), w: Math.round(0.42 * W), h: Math.round(0.62 * H), radius: 28 * u };
};

/** The take covers the box (like object-fit: cover), zoomed, keeping the focus framed and never showing an edge. */
export const cover = (box: Rect, zoom: number, focus = FOCUS): Rect => {
  const scale = Math.max(box.w / SOURCE.w, box.h / SOURCE.h) * zoom;
  const w = SOURCE.w * scale;
  const h = SOURCE.h * scale;
  const clamp = (v: number, min: number) => Math.min(0, Math.max(min, v));
  return { x: clamp(box.w / 2 - focus.x * scale, box.w - w), y: clamp(box.h * 0.45 - focus.y * scale, box.h - h), w, h };
};

const mix = (a: Box, b: Box, e: number): Box => ({
  x: a.x + (b.x - a.x) * e,
  y: a.y + (b.y - a.y) * e,
  w: a.w + (b.w - a.w) * e,
  h: a.h + (b.h - a.h) * e,
  radius: a.radius + (b.radius - a.radius) * e,
});

/**
 * B, frame `f` of segment `i`: even segments start fullscreen, have a punch-in (1.5-3 s) and spring into the card at
 * 4.5 s; odd ones start in the card and spring back to fullscreen at 5 s. Slow zoom from 1 to 1.06.
 */
export const frameB = (i: number, f: number, W: number, H: number): Frame => {
  const full: Box = { x: 0, y: 0, w: W, h: H, radius: 0 };
  const sp = (s: number) => spring({ frame: f - s * FPS, fps: FPS, config: { damping: 200 }, durationInFrames: 22 });
  const e = i % 2 === 0 ? sp(4.5) : 1 - sp(5);
  const box = mix(full, card(W, H), e);
  const slow = interpolate(f, [0, TAKE_FRAMES], [1, 1.06]);
  const punch =
    i % 2 === 0
      ? 0.12 * (spring({ frame: f - 1.5 * FPS, fps: FPS, config: { damping: 18 } }) - spring({ frame: f - 3 * FPS, fps: FPS, config: { damping: 18 } }))
      : 0;
  return { box, e, video: cover(box, slow + punch) };
};

/**
 * C, frame `f` of segment `i`: first half, a 2x2 grid of four takes; second half, one take fullscreen with another as
 * picture-in-picture. Boxes bottom to top.
 */
export const frameC = (i: number, f: number, W: number, H: number): { take: number; box: Box; video: Rect }[] => {
  const u = W / 1920;
  if (f < TAKE_FRAMES / 2) {
    const m = 24 * u;
    const w = (W - 3 * m) / 2;
    const h = (H - 3 * m) / 2;
    return [0, 1, 2, 3].map((k) => {
      const box = { x: m + (k % 2) * (w + m), y: m + Math.floor(k / 2) * (h + m), w, h, radius: 0 };
      return { take: i + k, box, video: cover(box, interpolate(f, [0, TAKE_FRAMES / 2], [1, 1.05])) };
    });
  }
  const full = { x: 0, y: 0, w: W, h: H, radius: 0 };
  const pip = { x: W - 560 * u - 40 * u, y: H - 315 * u - 40 * u, w: 560 * u, h: 315 * u, radius: 0 };
  return [
    { take: i, box: full, video: cover(full, interpolate(f, [TAKE_FRAMES / 2, TAKE_FRAMES], [1, 1.06])) },
    { take: i + 3, box: pip, video: cover(pip, 1) },
  ];
};
